String source = 'A1 B22 C333';
System.assertEquals('A0 B0 C0', source.replaceAll('([A-Z]+)([0-9]+)', '$10'));
System.assertEquals('$1 B22 C333', source.replaceFirst('([A-Z]+)([0-9]+)', '\$1'));
List<String> stringSplit = 'a,b,,'.split(',', -1);
System.assertEquals(4, stringSplit.size());
System.assertEquals('', stringSplit.get(3));

Pattern p = Pattern.compile('([A-Z]+)([0-9]+)?');
System.assertEquals('([A-Z]+)([0-9]+)?', p.pattern());
Matcher m = p.matcher('abc DEF42 ghi XYZ');
System.assertEquals(2, m.groupCount());
System.assert(m.find());
System.assertEquals('DEF42', m.group());
System.assertEquals(4, m.start());
System.assertEquals(9, m.end());
System.assertEquals('DEF', m.group(1));
System.assert(m.find());
System.assertEquals('XYZ', m.group(1));
System.assertEquals(null, m.group(2));
System.assertEquals(-1, m.start(2));
System.assertEquals(-1, m.end(2));

Matcher region = Pattern.compile('[A-Z]+').matcher('aa ABC bb DEF cc');
region.region(3, 6);
System.assert(region.lookingAt());
System.assert(region.matches());
System.assertEquals('ABC', region.group());
region.reset();
region.region(10, 13);
System.assert(region.matches());
System.assertEquals('DEF', region.group());
System.assertEquals('aa x bb DEF cc', Pattern.compile('[A-Z]+').matcher('aa ABC bb DEF cc').region(3, 10).replaceFirst('x'));
System.assertEquals('aa x bb x cc', Pattern.compile('[A-Z]+').matcher('aa ABC bb DEF cc').replaceAll('x'));

String literal = 'a+b?(x)[1]';
String quoted = Pattern.quote(literal);
System.assert(Pattern.matches(quoted, literal));
List<String> patternSplit = Pattern.compile(',').split('a,b,,', -1);
System.assertEquals(4, patternSplit.size());
System.assertEquals('', patternSplit.get(3));

